      // Rien de neuf : tout le fichier est déjà dans le journal → on retire les colonnes créées en anticipation.
      _customCols.forEach(cc => { const ix = _jrCols.findIndex(c => c.k === cc.k); if (ix >= 0) _jrCols.splice(ix, 1); });
