    if (opt.order) rows.sort((a, b) => opt.order.indexOf(a[0]) - opt.order.indexOf(b[0]));
    else rows.sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]));
    rows = rows.slice(0, opt.max || 18);
    const max = Math.max(1, ...rows.map(([, v]) => Math.abs(v)));
