      const arr = L.filter(e => _jrN(e.pl) != null).slice().sort((a, b) => (a.ts || 0) - (b.ts || 0));
      const fmtD = n => (n > 0 ? '+' : '') + (Math.round(n * 100) / 100).toLocaleString('fr-FR', { maximumFractionDigits: 2 }) + ' $';
